#!/usr/bin/env bash
set -euo pipefail
umask 077
RUN='<gpu-server-home>/experiments/SCI-sparse_normalizer_benchmark/2026-09-28_codex_mta_matched-bottomk-policy/runtime_cohorts/post_reboot_001'
test "$(id -un)" = canay
test "$(hostname)" = noron-HP-Elite-Tower-800-G9-Desktop-PC
cd "$RUN"
/usr/bin/python3 -B - <<'PY'
import base64, hashlib, json, os, sys
from pathlib import Path
run=Path.cwd()
assert str(run)=='<gpu-server-home>/experiments/SCI-sparse_normalizer_benchmark/2026-09-28_codex_mta_matched-bottomk-policy/runtime_cohorts/post_reboot_001'
sys.path.insert(0,str(run/'src'))
from support import verify_frozen, verify_release, verify_references
config,source=verify_frozen()
assert source=='2661B171DEC9AD49D031ACEA65F91F8BCE4C7C1CF8C3E317E3100EFFD8AC6B7C'
verify_release('smoke',config,source)
data=base64.b64decode('')
assert hashlib.sha256(data).hexdigest().upper()=='65C8B1AF457BDF93DF8A60E41EDD398AA8EBAE64BEF79CBAEBC244CDBB59A61F'
release=json.loads(data)
verify_references(release['references'],tuple(release['references']))
p=run/'admission/MAIN_RELEASE.json'
with p.open('xb') as f:
 f.write(data); f.flush(); os.fsync(f.fileno())
verify_release('main',config,source)
print(json.dumps({'status':'MAIN_RELEASE_BYTES_PUBLISHED_AND_FROZEN_API_VERIFIED_NOT_LAUNCHED','sha256':hashlib.sha256(data).hexdigest().upper(),'bytes':len(data)}))
PY
